INSERT INTO public.memorial_pages (created_by, full_name, birth_year, death_year, relationship_to_creator, personality_summary, unforgettable_moment, common_phrase, life_lesson, what_to_remember, status, activation_expiry) VALUES
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Grace Atieno', 1962, 2020, 'mother', 'Mama Grace had a laugh that filled the whole compound. She believed every visitor deserved tea, even the unannounced ones.', 'The night she stayed up sewing my school uniform after the rain ruined the first one — she never complained.', 'Hakuna jambo lisilo na suluhisho.', 'Kindness costs nothing but means everything.', 'Her warmth, her tea, and the way she made strangers feel like family.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Samuel Mwangi', 1948, 2019, 'grandfather', 'Babu Samuel was a quiet man who spoke through actions. He planted a tree for every grandchild born.', 'Walking with him through his shamba as he named every plant and what it had taught him.', 'A patient man eats ripe fruit.', 'Patience is a form of love.', 'The forest of trees he planted, each one carrying a name.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Faith Njeri', 1985, 2022, 'sister', 'Faith was the loudest cheerleader in any room. She remembered every birthday and never let one pass quietly.', 'When she drove four hours through the night just to be at my graduation the next morning.', 'You show up. That is the whole secret.', 'Showing up is the highest form of love.', 'Her presence — full, loud, and impossible to forget.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Daniel Otieno', 1955, 2021, 'father', 'Baba Daniel was a teacher in every setting. Even at the dinner table, he asked questions that made you think.', 'The Sunday afternoons spent reading the newspaper aloud and arguing politics with him.', 'Read everything. Believe slowly.', 'A questioning mind is the truest inheritance.', 'His library, his discipline, and the questions he taught us to keep asking.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Mercy Akinyi', 1978, 2023, 'friend', 'Mercy was the friend who texted at 2am just to say she was thinking of you. She remembered the small things.', 'The road trip to Kisumu where we got lost and laughed until our stomachs hurt.', 'Friendship is small things, often.', 'Real friendship lives in the small, frequent gestures.', 'Her voice notes, still saved on my phone, still making me laugh.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Joseph Kamau', 1940, 2018, 'grandfather', 'Mzee Joseph carried stories like other men carry tools — always ready to use one when the moment called for it.', 'The night he told us about meeting Mau Mau veterans, his voice low, the fire low, the room full.', 'A story shared is a country built.', 'Stories are how we keep each other alive.', 'His stories — the ones we wrote down, and the ones we wish we had.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Lillian Wambui', 1990, 2024, 'cousin', 'Lillian could turn any kitchen into a celebration. She believed food was the language of love.', 'Christmas Eve in her tiny apartment, twelve of us crammed around a table built for four.', 'Cook like you mean it.', 'Feeding people is one of love''s oldest languages.', 'Her recipes, written by hand, now passed between cousins.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Peter Ouma', 1965, 2017, 'uncle', 'Uncle Peter was the family fixer. Broken radios, broken hearts, broken plans — he had a way for all of them.', 'The afternoon he spent teaching me to ride a bicycle, refusing to let go until I told him to.', 'Most things can be fixed. The rest can be carried.', 'Some things heal. Others, we carry. Both are okay.', 'His toolbox, still in the garage, still useful.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Esther Wanjiru', 1972, 2022, 'aunt', 'Auntie Esther prayed loudly and laughed louder. Her faith was the kind that made room for everyone.', 'The harambee she organized for a stranger''s hospital bill — and how she made it feel like family.', 'Pray, then move your feet.', 'Faith without action is just decoration.', 'Her open door, her open hands, her open heart.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Michael Kiprop', 1958, 2020, 'mentor', 'Mwalimu Michael believed every student had a hidden gift. His job, he said, was just to help them find it.', 'The day he stayed two hours after class because I said I didn''t understand — and pretended he had nowhere else to be.', 'Every child is a closed letter. Open gently.', 'Teaching is just slow, patient love.', 'The students he shaped, now teachers themselves.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Ruth Chebet', 1968, 2023, 'mother', 'Mama Ruth ran a small kiosk and somehow knew every child''s name in the estate. She gave sweets on credit she never collected.', 'The morning she walked me to school in the rain, sharing one umbrella, both of us still soaked.', 'The shop is small. The heart is not.', 'Generosity isn''t a budget. It''s a posture.', 'Her kiosk, now run by my brother, still giving sweets on credit.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Anthony Maina', 1982, 2021, 'brother', 'Tony was the brother who showed up early, stayed late, and always carried a spare jacket in case someone forgot theirs.', 'The way he held my hand at our father''s funeral, neither of us speaking, both of us steady.', 'Just stand close. That''s usually enough.', 'Presence is louder than words.', 'His jacket, still hanging in the hallway. Still warm somehow.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Beatrice Awino', 1950, 2019, 'grandmother', 'Dani Beatrice braided hair, told dreams, and predicted weather better than the radio. She knew the land like a friend.', 'Sitting between her knees as she braided my hair and named every ancestor I came from.', 'Know your people. Then walk anywhere.', 'You walk taller when you know whose shoulders you''re standing on.', 'The names she taught me — a long line going back further than memory.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'George Mutiso', 1945, 2018, 'grandfather', 'Guka George was a carpenter who made furniture that outlived him. He signed his name on the underside of every piece.', 'Watching him build my first desk, sawdust in his beard, humming hymns under his breath.', 'Build it like someone you love will use it.', 'Do good work. Sign your name. Trust the years.', 'The desk I still write on, his initials still underneath.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Hannah Cherono', 1995, 2024, 'friend', 'Hannah was twenty-nine and made every room feel younger. She believed dancing was a form of prayer.', 'The wedding where she pulled the shyest aunties onto the dance floor and refused to let them sit down.', 'Dance now. The song is short.', 'Joy is a discipline, not a coincidence.', 'Her playlists, still shared, still played at every gathering.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Stephen Barasa', 1960, 2022, 'father', 'Baba Stephen was a bus driver who knew every road in western Kenya by feel. He could tell where he was just by the potholes.', 'The trip to Kakamega when he pulled over to show me the tree he''d climbed as a boy.', 'The road remembers you, even when you forget it.', 'Where you come from is a map you carry in your bones.', 'The routes he drove, the songs he played, the children he brought home safely.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Lucy Naliaka', 1975, 2023, 'sister', 'Lucy was the sister who corrected your grammar and your heart in the same sentence — and somehow you thanked her for both.', 'The night before my wedding, when she stayed up writing me a letter I still re-read every year.', 'Say the soft thing while you still can.', 'Tell people what they mean to you. Now. Not later.', 'Her letter, folded, refolded, still legible after all these years.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Patrick Onyango', 1970, 2020, 'uncle', 'Uncle Patrick was a fisherman on Lake Victoria. He read the water like other men read books.', 'The dawn he took me out on the boat and didn''t speak for two hours — and I understood every word.', 'The lake teaches what books cannot.', 'Some lessons only silence can deliver.', 'The stillness he taught me. The patience of waiting for the line to pull.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Margaret Wairimu', 1953, 2021, 'mother', 'Mama Margaret was a nurse for forty-one years. She held more hands at last breaths than most of us will hold in a lifetime.', 'When she came home after a hard shift, sat on the veranda, and just looked at the sky for a long time.', 'Be gentle. Everyone is carrying something.', 'Tenderness is not weakness — it is the strongest thing we have.', 'Her uniform, pressed and folded, kept by my sister who became a nurse too.', 'active', now() + interval '1 year'),
('8bd30056-3f61-4d9b-930c-7752f01eab7f', 'Isaac Kibet', 1988, 2024, 'brother', 'Isaac ran every morning, even in the rain. He said running was where he met himself again, fresh, every day.', 'The marathon we ran together — me limping by kilometre 30, him slowing down to finish beside me.', 'Run your own race. But never alone if you can help it.', 'We finish further when we finish together.', 'His running shoes, still by the door, as if he''ll be back any morning now.', 'active', now() + interval '1 year');
